float shuntVoltage_mV = 0.0;
float current_A       = 0.0;

// Smoothed current shown on dashboard
float filteredCurrent_A = 0.0;

// Highest absolute current seen this session
float peakCurrent_A = 0.0;

// Amp-hours accumulated during this session
float sessionAh = 0.0;

// Sampling
const unsigned long SAMPLE_INTERVAL_MS = 100;

unsigned long lastSampleMillis = 0;

// Session timing
unsigned long sessionStartMillis = 0;

// =====================================================
// INA226 REGISTER READ
// =====================================================

bool readINA226Register(
  uint8_t reg,
  int16_t &value
) {

  Wire.beginTransmission(
    INA226_ADDRESS
  );

  Wire.write(reg);

  if (
    Wire.endTransmission(false) != 0
  ) {

    return false;
  }

  Wire.requestFrom(
    INA226_ADDRESS,
    (uint8_t)2
  );

  if (Wire.available() < 2) {

    return false;
  }

  uint16_t raw =
    ((uint16_t)Wire.read() << 8) |
    Wire.read();

  value = (int16_t)raw;

  return true;
}

// =====================================================
// READ SHUNT VOLTAGE
// =====================================================

bool readShuntVoltage(
  float &millivolts
) {

  int16_t raw;

  // INA226 register 0x01 =
  // Shunt Voltage Register

  if (
    !readINA226Register(
      0x01,
      raw
    )
  ) {

    return false;
  }

  float volts =
    raw *
    INA226_SHUNT_LSB_V;

  millivolts =
    volts * 1000.0;

  return true;
}

// =====================================================
// BATTERY MONITOR SAMPLING
// =====================================================

void updateBatteryMonitor() {

  unsigned long now =
    millis();

  if (
    now - lastSampleMillis <
    SAMPLE_INTERVAL_MS
  ) {

    return;
  }

  // Actual elapsed time since last sample
  unsigned long elapsedMs =
    now - lastSampleMillis;

  lastSampleMillis = now;

  float newShunt_mV;

  if (
    !readShuntVoltage(
      newShunt_mV
    )
  ) {

    return;
  }

  // -----------------------------------------------
  // SHUNT VOLTAGE
  // -----------------------------------------------

  shuntVoltage_mV =
    newShunt_mV;

  // -----------------------------------------------
  // CURRENT
  //
  // I = V / R
  // -----------------------------------------------

  float shuntVoltage_V =
    shuntVoltage_mV /
    1000.0;

  current_A =
    shuntVoltage_V /
    SHUNT_OHMS;

  // -----------------------------------------------
  // SMALL ZERO DEAD-BAND
  //
  // Prevent tiny microvolt noise from
  // accumulating fake Ah while everything is off.
  // -----------------------------------------------

  if (
    current_A > -0.01 &&
    current_A < 0.01
  ) {

    current_A = 0.0;
  }

  // -----------------------------------------------
  // FILTERED CURRENT
  //
  // Mild exponential smoothing.
  // Raw current is still used for peak detection.
  // -----------------------------------------------

  const float alpha = 0.25;

  filteredCurrent_A =
    (alpha * current_A) +
    ((1.0 - alpha) *
     filteredCurrent_A);

  // -----------------------------------------------
  // PEAK CURRENT
  // -----------------------------------------------

  float absCurrent =
    fabs(current_A);

  if (
    absCurrent >
    peakCurrent_A
  ) {

    peakCurrent_A =
      absCurrent;
  }

  // -----------------------------------------------
  // AMP-HOURS
  //
  // Ah = A * hours
  //
  // elapsedMs / 3,600,000
  // converts milliseconds to hours.
  // -----------------------------------------------

  float elapsedHours =
    elapsedMs /
    3600000.0;

  sessionAh +=
    current_A *
    elapsedHours;
}

// =====================================================
// RESET SESSION
// =====================================================

void resetSession() {

  peakCurrent_A = 0.0;

  sessionAh = 0.0;

  sessionStartMillis =
    millis();
}

// =====================================================
// FORMAT RUNTIME
// =====================================================

String formatRuntime() {

  unsigned long elapsedSeconds =
    (millis() -
     sessionStartMillis) /
    1000;

  unsigned long hours =
    elapsedSeconds /
    3600;

  unsigned long minutes =
    (elapsedSeconds % 3600) /
    60;

  unsigned long seconds =
    elapsedSeconds % 60;

  char buffer[20];

  snprintf(
    buffer,
    sizeof(buffer),
    "%02lu:%02lu:%02lu",
    hours,
    minutes,
    seconds
  );

  return String(buffer);
}

// =====================================================
// LIGHTING FUNCTIONS
// =====================================================

void showCurrentColor() {

  if (!lightsOn) {

    strip.clear();
    strip.show();

    return;
  }

  for (
    int i = 0;
    i < LED_COUNT;
    i++
  ) {

    strip.setPixelColor(
      i,
      strip.Color(
        currentR,
        currentG,
        currentB
      )
    );
  }

  strip.show();
}

void setColor(
  uint8_t r,
  uint8_t g,
  uint8_t b
) {

  currentR = r;
  currentG = g;
  currentB = b;

  lightsOn = true;

  showCurrentColor();
}

void returnHome() {

  server.sendHeader(
    "Location",
    "/"
  );

  server.send(
    303,
    "text/plain",
    ""
  );
}

